public void withPostsActionInvokedEvent() {
    class Customer {

        class SomeActionInvokedDomainEvent extends ActionInvokedEvent<Customer> {

            public SomeActionInvokedDomainEvent(final Customer source, final Identifier identifier, final Object... arguments) {
                super(source, identifier, arguments);
            }
        }

